// Pure bid arithmetic for a biohazard / trauma-scene remediation job
// (unattended death, crime scene, industrial accident, or hoarding-biohazard
// cleanup). No network, no state: every hour, rate, pound, and fee is an
// input, so the result stays a transparent calculation the technician can
// check against their own hauler invoice and PPE order instead of a rule of
// thumb like "day rate plus a flat hazmat fee."
//
// The buyer: a licensed biohazard/trauma remediation technician or small
// company (often cross-licensed for mold or water-damage restoration) who
// quotes a scene cleanup — usually billed to the property owner, sometimes
// routed through homeowner's insurance, but priced here purely as the
// company's own cost-plus job, the same way this portfolio's other
// remediation calculators price a mold or radon job rather than adjudicate
// an insurance claim.
//
// Two costs a flat day-rate-plus-hazmat-fee spreadsheet gets wrong, and both
// are modeled here rather than assumed away:
//
//   1. Regulated (biohazard/medical) waste disposal is billed by the
//      licensed waste hauler **per container picked up, not per pound**. A
//      container that is 10% full costs exactly what one that is 100% full
//      costs, up to that container's rated capacity — so a naive
//      `totalPounds * (costPerContainer / containerCapacityPounds)` estimate
//      undercounts every job whose waste does not divide evenly into whole
//      containers. `disposalCost` rounds the pound estimate up to the next
//      whole container before pricing it, the way the hauler's own invoice
//      will.
//   2. PPE cost scales with **decontamination cycles, not headcount.** A
//      technician who leaves the contaminated area — for a break, to run
//      equipment out, or because the job spans a shift change — must doff
//      the PPE they were wearing (it cannot be re-donned once removed) and
//      don a fresh set to re-enter. `ppeCost` is technicians times cycles
//      per technician, not technicians times one, so a job with more than
//      one cycle per tech costs more PPE than a naive per-head count
//      assumes.
//
//   calculateJobBid(inputs)        -- full cost breakdown, the naive
//                                      per-pound/per-head comparison, and
//                                      the quoted price for one job.
//   formatBidBreakdown(result)     -- the same breakdown as plain text, for
//                                      pasting into an invoice or an email.

function number(value, name, { min = 0, allowZero = true } = {}) {
  const result = Number(value);
  if (!Number.isFinite(result)) throw new Error(`${name} must be a number`);
  if (result < min) throw new Error(`${name} must be at least ${min}`);
  if (!allowZero && result === 0) throw new Error(`${name} must be greater than zero`);
  return result;
}

function round2(n) {
  return Math.round((n + Number.EPSILON) * 100) / 100;
}

export const DEFAULTS = {
  technicianCount: 2,
  hoursOnSitePerTechnician: 5,
  laborRatePerHour: 45,
  deconCyclesPerTechnician: 1,
  ppeCostPerSet: 38,
  suppliesCost: 120,
  equipmentRentalCost: 90,
  biohazardWastePounds: 55,
  containerCapacityPounds: 40,
  costPerContainer: 110,
  travelFee: 75,
  minimumJobFee: 650,
  targetMarginPercent: 25,
};

/**
 * Price one biohazard / trauma-scene remediation job.
 *
 * @param {object} input
 * @param {number} input.technicianCount           Techs working the scene.
 * @param {number} input.hoursOnSitePerTechnician   Hours each tech spends
 *   on site (setup, cleaning, decon, teardown combined).
 * @param {number} input.laborRatePerHour           Loaded hourly rate for
 *   one technician's time.
 * @param {number} input.deconCyclesPerTechnician   Times each technician
 *   dons a fresh PPE set to (re-)enter the contaminated area over the job
 *   (>= 1 — every tech dons at least once). Raise this for breaks, a
 *   multi-day job, or an equipment run that requires re-entry.
 * @param {number} input.ppeCostPerSet              Cost of one full PPE
 *   set: suit, respirator, gloves, booties, eye protection.
 * @param {number} input.suppliesCost               Flat consumables for
 *   the job: enzymatic cleaner, sealant, odor treatment, absorbents.
 * @param {number} input.equipmentRentalCost        Flat equipment for the
 *   job: ozone generator, air scrubber, sub-floor injectors.
 * @param {number} input.biohazardWastePounds       Estimated weight of
 *   regulated waste the job will generate.
 * @param {number} input.containerCapacityPounds    Pounds one approved
 *   disposal container holds, per your hauler's spec sheet.
 * @param {number} input.costPerContainer           Your hauler's charge
 *   per container picked up, regardless of how full it is.
 * @param {number} input.travelFee                  Flat trip charge.
 * @param {number} input.minimumJobFee              Your company's minimum
 *   charge for any job, regardless of computed scope.
 * @param {number} input.targetMarginPercent        Desired profit margin
 *   on top of direct cost (0-99).
 * @param {number|null} [input.proposedPrice]       A price you are
 *   actually quoting (or considering), to check its real profit and margin
 *   against the true floor instead of the suggested price.
 */
export function calculateJobBid(input = {}) {
  const technicianCount = number(input.technicianCount, 'Technician count', { allowZero: false });
  const hoursOnSitePerTechnician = number(input.hoursOnSitePerTechnician, 'Hours on site per technician', { allowZero: false });
  const laborRatePerHour = number(input.laborRatePerHour, 'Labor rate');
  const deconCyclesPerTechnician = number(input.deconCyclesPerTechnician, 'Decon cycles per technician', { min: 1, allowZero: false });
  const ppeCostPerSet = number(input.ppeCostPerSet, 'PPE cost per set');
  const suppliesCost = number(input.suppliesCost, 'Supplies cost');
  const equipmentRentalCost = number(input.equipmentRentalCost, 'Equipment rental cost');
  const biohazardWastePounds = number(input.biohazardWastePounds, 'Biohazard waste (lb)');
  const containerCapacityPounds = number(input.containerCapacityPounds, 'Container capacity (lb)', { allowZero: false });
  const costPerContainer = number(input.costPerContainer, 'Cost per container');
  const travelFee = number(input.travelFee, 'Travel fee');
  const minimumJobFee = number(input.minimumJobFee, 'Minimum job fee');
  const targetMarginPercent = number(input.targetMarginPercent, 'Target margin');
  if (targetMarginPercent >= 100) throw new Error('Target margin must be less than 100%');

  const laborCost = round2(technicianCount * hoursOnSitePerTechnician * laborRatePerHour);

  const ppeSets = technicianCount * deconCyclesPerTechnician;
  const ppeCost = round2(ppeSets * ppeCostPerSet);
  // What a headcount-only estimate (one set per tech, no decon cycles)
  // would have charged for PPE — the gap is what extra decon cycles cost.
  const naivePpeCost = round2(technicianCount * ppeCostPerSet);
  const ppeUndercount = round2(Math.max(0, ppeCost - naivePpeCost));

  const containersNeeded = biohazardWastePounds > 0
    ? Math.ceil(biohazardWastePounds / containerCapacityPounds)
    : 0;
  const disposalCost = round2(containersNeeded * costPerContainer);
  const unusedContainerCapacityPounds = round2(
    containersNeeded > 0 ? containersNeeded * containerCapacityPounds - biohazardWastePounds : 0,
  );
  // What a naive per-pound estimate (linear rate, no rounding to a whole
  // container) would have charged for disposal — the gap is what the
  // container-rounding rule actually costs.
  const naiveDisposalCost = round2(biohazardWastePounds * (costPerContainer / containerCapacityPounds));
  const disposalUndercount = round2(Math.max(0, disposalCost - naiveDisposalCost));

  const directCost = round2(
    laborCost + ppeCost + suppliesCost + equipmentRentalCost + disposalCost + travelFee,
  );
  const marginPrice = round2(directCost / (1 - targetMarginPercent / 100));
  const minimumApplied = marginPrice < minimumJobFee;
  const price = minimumApplied ? round2(minimumJobFee) : marginPrice;
  const profit = round2(price - directCost);
  const effectiveMarginPercent = price === 0 ? 0 : round2((profit / price) * 100);

  const naiveDirectCost = round2(
    laborCost + naivePpeCost + suppliesCost + equipmentRentalCost + naiveDisposalCost + travelFee,
  );
  const naiveUndercount = round2(Math.max(0, directCost - naiveDirectCost));

  const hasProposed = input.proposedPrice !== null && input.proposedPrice !== undefined && input.proposedPrice !== '';
  let proposed = null;
  if (hasProposed) {
    const proposedPrice = number(input.proposedPrice, 'Price you are considering', { allowZero: false });
    const proposedProfit = round2(proposedPrice - directCost);
    proposed = {
      price: proposedPrice,
      profit: proposedProfit,
      marginPercent: proposedPrice === 0 ? 0 : round2((proposedProfit / proposedPrice) * 100),
      belowDirectCost: proposedProfit < 0,
    };
  }

  const findings = [];

  if (deconCyclesPerTechnician > 1) {
    findings.push({
      id: 'decon-cycles-raise-ppe',
      severity: 'info',
      title: `${ppeSets} PPE sets needed for ${technicianCount} tech(s) at ${deconCyclesPerTechnician} decon cycle(s) each — $${ppeUndercount.toFixed(2)} more than a per-head estimate`,
      detail: 'A technician who leaves the contaminated area must doff and dispose of the PPE they were wearing before re-entering in a fresh set — used PPE cannot be re-donned. A count that assumes one set per technician undercounts every job with a break, an equipment run, or a shift change.',
    });
  }

  if (containersNeeded > 0 && unusedContainerCapacityPounds > 0) {
    findings.push({
      id: 'container-rounding',
      severity: 'medium',
      title: `${containersNeeded} container(s) needed, with ${unusedContainerCapacityPounds.toFixed(1)} lb of paid-for capacity unused — $${disposalUndercount.toFixed(2)} more than a per-pound rate`,
      detail: 'Regulated waste haulers bill per container picked up, not per pound. A container that is only partly full still costs the full per-container charge, so an estimate of pounds times a per-pound rate undercounts unless the waste happens to divide evenly into whole containers.',
    });
  }

  if (minimumApplied) {
    findings.push({
      id: 'minimum-job-fee-applied',
      severity: 'info',
      title: `Margin-based price ($${marginPrice.toFixed(2)}) was below your $${minimumJobFee.toFixed(2)} minimum — quoted at the minimum instead`,
      detail: 'Small scopes (one room, a short on-site window, little waste) can price below your minimum job fee on cost-plus-margin alone. The minimum protects against under-billing a job that still requires a full truck roll, a hauler pickup, and travel regardless of scope.',
    });
  }

  findings.push({
    id: 'confirm-before-quoting',
    severity: 'medium',
    title: 'Confirm your hauler contract and local protocol before quoting',
    detail: 'This totals the rates, hours, and waste estimate you entered — it does not know your regulated-waste hauler’s actual per-container price, your state or OSHA bloodborne-pathogen decon requirements, or whether a given job is billable to insurance. Confirm those before sending a quote or filing a waste manifest.',
  });

  return {
    technicianCount,
    hoursOnSitePerTechnician,
    laborRatePerHour,
    laborCost,
    deconCyclesPerTechnician,
    ppeSets,
    ppeCost,
    naivePpeCost,
    ppeUndercount,
    suppliesCost,
    equipmentRentalCost,
    biohazardWastePounds,
    containerCapacityPounds,
    containersNeeded,
    unusedContainerCapacityPounds,
    disposalCost,
    naiveDisposalCost,
    disposalUndercount,
    costPerContainer,
    travelFee,
    directCost,
    naiveDirectCost,
    naiveUndercount,
    marginPrice,
    minimumJobFee,
    minimumApplied,
    targetMarginPercent,
    price,
    profit,
    effectiveMarginPercent,
    proposed,
    findings,
  };
}

/**
 * The disclaimer that travels with a copied breakdown -- the text leaves
 * this page and its reader may never see the footer.
 */
export const BREAKDOWN_DISCLAIMER =
  'Arithmetic only: this breakdown totals the rates, hours, and waste estimate ' +
  'you entered. It does not know your regulated-waste hauler’s actual ' +
  'per-container price, your state or OSHA bloodborne-pathogen decon ' +
  'requirements, or whether a job is billable to insurance -- confirm those ' +
  'before quoting or filing a waste manifest.';

/**
 * Renders a job bid as the plain-text breakdown a technician can paste into
 * an invoice, a work order, or an email to the property owner.
 *
 * @param {ReturnType<typeof calculateJobBid>} result
 * @returns {string}
 */
export function formatBidBreakdown(result) {
  const money = (n) => {
    const format = (v) => `$${v.toLocaleString('en-US', { minimumFractionDigits: 2, maximumFractionDigits: 2 })}`;
    const text = format(Math.abs(n));
    return n < 0 && /[1-9]/.test(text) ? `-${text}` : text;
  };
  const {
    technicianCount = 0, hoursOnSitePerTechnician = 0, laborCost = 0,
    ppeSets = 0, ppeCost = 0, containersNeeded = 0, disposalCost = 0,
    suppliesCost = 0, equipmentRentalCost = 0, travelFee = 0,
    directCost = 0, price = 0, profit = 0, minimumApplied = false,
  } = result ?? {};

  const lines = ['BIOHAZARD / TRAUMA-SCENE CLEANUP JOB BID', ''];
  lines.push(`Technicians: ${technicianCount} x ${hoursOnSitePerTechnician} h on site = ${money(laborCost)} labor`);
  lines.push(`PPE: ${ppeSets} set(s) = ${money(ppeCost)}`);
  lines.push(`Regulated waste disposal: ${containersNeeded} container(s) = ${money(disposalCost)}`);
  lines.push(`Supplies: ${money(suppliesCost)}`);
  lines.push(`Equipment rental: ${money(equipmentRentalCost)}`);
  lines.push(`Travel: ${money(travelFee)}`);
  lines.push('', `Direct cost: ${money(directCost)}`);
  lines.push(`Quoted price${minimumApplied ? ' (minimum job fee applied)' : ''}: ${money(price)}`);
  lines.push(`Profit at this price: ${money(profit)}`);
  lines.push('', '--', BREAKDOWN_DISCLAIMER);

  return lines.join('\n');
}

proposal.mjs.text:
// Turns a finished bid into the document the contractor actually hands the
// customer: a one-page proposal they can print or "Save as PDF" from the
// browser.
//
// Why this exists
// ---------------
// Every bid calculator in this portfolio already ends at a number and a
// plain-text blurb to paste somewhere. That is where the tool stops and the
// contractor's evening starts: retyping the scope into Word, remembering the
// deposit split, guessing how long the price should stand. The proposal is the
// thing that wins or loses the job, and it was the one artifact none of these
// tools produced.
//
// Deliberately NOT a contract
// ---------------------------
// This renders the contractor's own words and numbers into a tidy layout. It
// invents no legal terms, warranties, lien language, or cancellation rights —
// every clause on the page is text the user typed or left blank. A "proposal"
// that shipped boilerplate terms drafted by a calculator would be exactly the
// legal exposure `PRODUCT_PLAYBOOK.md` §5b tells us to avoid, and it would be
// wrong in most jurisdictions anyway.
//
// Privacy
// -------
// `loadCompany` / `saveCompany` persist the *contractor's own* business block
// (their name, phone, licence) so they type it once. The customer's name and
// address are never persisted: that is a third party's personal data sitting on
// someone else's device, and re-typing it per job is cheap. Nothing here
// touches the network.
//
// This file is generic on purpose — no trade, no venture, no storage key baked
// in — so it can be copied verbatim into any calculator in `ventures/`. See the
// venture README for the wiring steps.

/** Fields of the contractor's own business block, in display order. */
export const COMPANY_FIELDS = Object.freeze([
  'companyName', 'companyPhone', 'companyEmail', 'companyLicense', 'companyAddress',
]);

/** Fields describing the customer and the job. Never persisted. */
export const CLIENT_FIELDS = Object.freeze([
  'clientName', 'clientAddress',
]);

/** Commercial terms the contractor controls. */
export const TERM_FIELDS = Object.freeze([
  'depositPercent', 'validDays', 'paymentTerms', 'proposalNotes', 'proposalExclusions',
]);

export function escapeHtml(value) {
  return String(value ?? '')
    .replaceAll('&', '&amp;')
    .replaceAll('<', '&lt;')
    .replaceAll('>', '&gt;')
    .replaceAll('"', '&quot;')
    .replaceAll("'", '&#39;');
}

function text(value) {
  return String(value ?? '').trim();
}

function number(value, name, { min = 0, max = Infinity } = {}) {
  const result = Number(value);
  if (!Number.isFinite(result)) throw new Error(`${name} must be a number`);
  if (result < min) throw new Error(`${name} must be at least ${min}`);
  if (result > max) throw new Error(`${name} must be at most ${max}`);
  return result;
}

/**
 * A figure for the customer's copy.
 *
 * `currency` defaults to `'$'`, which is what every trade in this portfolio
 * quotes in and what all 102 adopters rendered before it was a parameter — so
 * an unchanged caller gets a byte-identical document.
 *
 * It exists because the document is not only a US construction bid. A
 * freelancer quoting a translation names their own currency on the page, and
 * printing `$1,200.00` on a quote the client will pay in euros is not a display
 * nicety: it misstates the price on the one sheet that is meant to settle it.
 * The venture passes whatever its own currency field says.
 *
 * A label is spaced from the figure and a symbol is not — `USD 1,200.00` but
 * `$1,200.00` and `€1,200.00` — decided by whether the currency ends in a
 * letter, which is the only difference a reader would notice between the two.
 *
 * That space is a non-breaking one, written as an escape so it cannot be
 * mistaken for an ordinary space by anyone reading this file or matching
 * against its output. A quote is a printed document with a narrow price
 * column, and "USD" left stranded at the end of a line with its figure on the
 * next is the one place this layout can break in a way the customer sees.
 */
export function money(value, currency = '$') {
  // Sign goes outside the currency symbol: "-$9.24", not "$-9.24". The old
  // spelling put it inside, which is what interpolating a negative straight
  // after a "$" gets you, and it reads as a typo on a document a contractor
  // hands a customer.
  //
  // Round to cents *before* choosing the sign. A delta of two equal figures
  // lands on -0, and a residual like -0.004 rounds to zero at cent precision;
  // both used to print "$-0.00" — a line that is exactly break-even claiming
  // to be down money.
  const cents = Math.round(Math.abs(value) * 100);
  const sign = cents === 0 ? '' : value < 0 ? '-' : '';
  const amount = (cents / 100).toLocaleString('en-US', {
    minimumFractionDigits: 2,
    maximumFractionDigits: 2,
  });
  const unit = text(currency) || '$';
  return `${sign}${unit}${/[A-Za-z]$/.test(unit) ? '\u00a0' : ''}${amount}`;
}

/**
 * Split a textarea into trimmed, non-empty lines. Blank lines are how people
 * space out a scope list; they should not become empty bullets.
 */
export function lines(value) {
  return text(value)
    .split('\n')
    .map((line) => line.trim())
    .filter(Boolean);
}

/**
 * Fill scope templates from a calculator's result, dropping any line whose
 * figures are not there.
 *
 * Every adoption batch so far has lost a line to the same defect: each
 * calculator names its result differently, `result.doorClass` or `run.material`
 * resolves to `undefined` rather than throwing, and the customer's scope reads
 * "undefined ft of undefined" while every suite stays green. Guessing is the
 * problem; this makes guessing wrong *visible* instead of silent.
 *
 * A template is `'Install {totalLinearFeet} ft of {fenceName}'`, or an object
 * `{ line, when }` where `when` names a field that must be truthy for the line
 * to appear at all.
 *
 * `{ each, line, when }` renders one line **per element** of the array at
 * `each`, with `{field}` reading that element rather than the result root.
 * Half the calculators here price an itemised job — rooms of flooring, gutter
 * runs, trees, kitchen exhaust components — and a homeowner collecting three
 * bids compares the line items, not a total. Without this the only scope such
 * a trade could draft is "Perform the work described above", which the README
 * is explicit is worth less than no proposal at all. `when` is read against
 * the element too, so a row the contractor left at zero stays off the quote:
 *
 * ```json
 * { "each": "rooms", "when": "hours", "line": "{name} — {squareFeet~0} sq ft" }
 * ```
 *
 * Elements are not truncated. Every row the contractor entered is a row they
 * intend to be paid for, and "…and 4 more" on a document someone signs is a
 * dispute waiting to happen.
 *
 * `{field+s}` is that field's plural suffix — `'s'` unless the value is exactly
 * one — so `'{gates} gate{gates+s}'` reads "1 gate" and "3 gates". Without it
 * the obvious thing to write is `'{gates} gate{gates}'`, which prints
 * "3 gate3" on a customer's quote.
 *
 * `{field~2}` rounds to that many decimals and groups thousands, so a derived
 * figure reads "48.89 yd²" and "1,600 sq ft" rather than "48.888888888888886"
 * and "1600". Anything computed — a yardage, a tonnage, a square count — needs
 * it: a quote carrying fifteen decimal places tells the customer the number was
 * produced by a machine that was not being watched.
 *
 * A placeholder that resolves to `undefined`, `null`, `''`,
 * `NaN`, or `Infinity` drops its whole line — a scope with one line missing is
 * a scope the contractor edits, whereas a scope reading `undefined` is one they
 * hand to a customer without noticing.
 *
 * Dropping is not the safety property on its own: an empty scope is also wrong,
 * and `platform/proposal/verify.mjs` fails a page whose default scope comes out
 * empty. Between them, a mis-named field cannot reach a customer quietly.
 *
 * @param {Array<string|{line: string, when?: string, each?: string}>} templates
 * @param {object} values The calculator's result (and anything else to read).
 * @returns {string[]}
 */
export function scopeLines(templates, values) {
  const missing = (value) => value === undefined || value === null || value === ''
    || (typeof value === 'number' && !Number.isFinite(value));

  const readFrom = (scope, path) => String(path).split('.')
    .reduce((node, key) => (node === null || node === undefined ? undefined : node[key]), scope);

  /**
   * One template line against one scope, or `null` if any placeholder in it is
   * missing. Shared by plain lines and `each` rows on purpose: a row must drop
   * on a missing figure by exactly the same rule as a top-level line, or the
   * word "undefined" reaches the customer through whichever path was written
   * second.
   */
  const render = (line, scope) => {
    let complete = true;
    const rendered = line.replace(
      /\{([A-Za-z0-9_.]+?)(?:\+([A-Za-z]+)|~(\d))?\}/g,
      (_match, path, plural, decimals) => {
        const value = readFrom(scope, path);
        if (missing(value)) { complete = false; return ''; }
        if (plural !== undefined) return Number(value) === 1 ? '' : plural;
        if (decimals !== undefined) {
          const number = Number(value);
          if (!Number.isFinite(number)) { complete = false; return ''; }
          return number.toLocaleString('en-US', {
            minimumFractionDigits: 0,
            maximumFractionDigits: Number(decimals),
          });
        }
        return String(value);
      },
    );
    return complete && rendered.trim() ? rendered.trim() : null;
  };

  const filled = [];
  for (const template of templates ?? []) {
    const line = typeof template === 'string' ? template : template?.line;
    if (typeof line !== 'string') continue;
    const each = typeof template === 'object' ? template.each : undefined;

    if (each !== undefined) {
      const rows = readFrom(values, each);
      if (!Array.isArray(rows)) continue;
      for (const row of rows) {
        if (row === null || typeof row !== 'object') continue;
        if (template.when !== undefined && !readFrom(row, template.when)) continue;
        const rendered = render(line, row);
        if (rendered !== null) filled.push(rendered);
      }
      continue;
    }

    if (typeof template === 'object' && template.when !== undefined && !readFrom(values, template.when)) continue;
    const rendered = render(line, values);
    if (rendered !== null) filled.push(rendered);
  }
  return filled;
}

/**
 * `YYYY-MM-DD` plus a whole number of days, in UTC.
 *
 * Local-time date arithmetic silently shifts by a day across a DST boundary,
 * which on a quote-expiry date is a real dispute with a customer.
 */
export function addDays(isoDate, days) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text(isoDate));
  if (!match) throw new Error('Issue date must be YYYY-MM-DD');
  const [, year, month, day] = match;
  const stamp = Date.UTC(Number(year), Number(month) - 1, Number(day));
  if (Number.isNaN(stamp)) throw new Error('Issue date must be a real date');
  return new Date(stamp + number(days, 'Valid days') * 86_400_000)
    .toISOString()
    .slice(0, 10);
}

/** `2026-08-26` → `26 August 2026`. Unambiguous to both US and non-US readers. */
export function formatDate(isoDate) {
  const match = /^(\d{4})-(\d{2})-(\d{2})$/.exec(text(isoDate));
  if (!match) return text(isoDate);
  const [, year, month, day] = match;
  const monthName = new Date(Date.UTC(Number(year), Number(month) - 1, 1))
    .toLocaleDateString('en-US', { month: 'long', timeZone: 'UTC' });
  return `${Number(day)} ${monthName} ${year}`;
}

/**
 * A short, stable reference the contractor and the customer can both quote on
 * the phone. Derived from the issue date and the customer name so that
 * re-printing the same proposal gives the same number, and two proposals
 * written the same day for different customers do not collide.
 */
export function referenceFor(issuedOn, clientName) {
  const compact = text(issuedOn).replaceAll('-', '');
  let hash = 0;
  for (const character of text(clientName).toUpperCase()) {
    hash = (hash * 31 + character.codePointAt(0)) % 1_048_576;
  }
  return `Q-${compact}-${hash.toString(36).toUpperCase().padStart(4, '0').slice(-4)}`;
}

/**
 * Assemble and validate a proposal.
 *
 * Throws on the things that would embarrass the contractor in front of a
 * customer — no business name, no customer name, a zero price, a deposit over
 * 100% — rather than rendering a document with a hole in it.
 */
export function buildProposal(input = {}) {
  const companyName = text(input.companyName);
  if (!companyName) throw new Error('Add your business name before printing a proposal');
  const clientName = text(input.clientName);
  if (!clientName) throw new Error('Add the customer name before printing a proposal');

  const price = number(input.price, 'Price', { min: 0 });
  if (price <= 0) throw new Error('Price a job before printing a proposal');

  const depositPercent = number(input.depositPercent ?? 0, 'Deposit', { min: 0, max: 100 });
  const validDays = number(input.validDays ?? 0, 'Valid days', { min: 0, max: 3650 });
  const issuedOn = text(input.issuedOn) || new Date().toISOString().slice(0, 10);

  // Rounded to cents here, not at display time, and the balance taken as the
  // remainder. The customer adds the two lines up: if the deposit rounds up and
  // the balance rounds down independently, the printed figures miss the printed
  // total by a cent, and the contractor has to explain it on the phone.
  const depositAmount = Math.round(price * depositPercent) / 100;

  return {
    reference: referenceFor(issuedOn, clientName),
    issuedOn,
    validDays,
    validUntil: validDays === 0 ? null : addDays(issuedOn, validDays),
    company: {
      name: companyName,
      phone: text(input.companyPhone),
      email: text(input.companyEmail),
      license: text(input.companyLicense),
      address: text(input.companyAddress),
    },
    client: {
      name: clientName,
      address: text(input.clientAddress),
    },
    job: {
      title: text(input.jobTitle) || 'Proposed work',
      scope: lines(input.scope),
      exclusions: lines(input.proposalExclusions),
      notes: text(input.proposalNotes),
    },
    pricing: {
      price,
      depositPercent,
      depositAmount,
      balanceAmount: price - depositAmount,
      paymentTerms: text(input.paymentTerms),
    },
  };
}

function block(title, body) {
  return body ? `<div class="pr-block"><h3>${escapeHtml(title)}</h3>${body}</div>` : '';
}

function list(items) {
  return items.length === 0
    ? ''
    : `<ul>${items.map((item) => `<li>${escapeHtml(item)}</li>`).join('')}</ul>`;
}

function paragraphs(value) {
  return value ? `<p>${escapeHtml(value).replaceAll('\n', '<br>')}</p>` : '';
}

/**
 * Render the proposal as the HTML that goes inside the page's print container.
 *
 * Returns a fragment, not a whole document: the page owns the print stylesheet,
 * so the same markup is what the contractor previews on screen and what comes
 * out of the printer. A separate print-only document is how the two drift.
 *
 * @param {ReturnType<typeof buildProposal>} proposal
 * @param {object} [options]
 * @param {string} [options.disclaimer] Sentence to print in the footer. The
 *   caller supplies it so each trade can name its own regulator and scope.
 * @param {string} [options.currency] Prefix for every figure on the sheet.
 *   Defaults to `'$'`; see `money`.
 */
export function renderProposalHtml(proposal, { disclaimer = '', currency = '$' } = {}) {
  const { company, client, job, pricing } = proposal;
  const amount = (value) => money(value, currency);

  const contact = [company.phone, company.email, company.address]
    .filter(Boolean)
    .map((line) => `<span>${escapeHtml(line)}</span>`)
    .join('');

  const validity = proposal.validUntil
    ? `<p class="pr-validity">This price is held until <strong>${escapeHtml(formatDate(proposal.validUntil))}</strong> (${proposal.validDays} days from issue).</p>`
    : '';

  const depositRow = pricing.depositPercent > 0
    ? `<tr><td>Deposit due on acceptance (${pricing.depositPercent}%)</td><td>${amount(pricing.depositAmount)}</td></tr>
       <tr><td>Balance due on completion</td><td>${amount(pricing.balanceAmount)}</td></tr>`
    : '';

  return `
    <article class="pr-doc">
      <header class="pr-head">
        <div>
          <h2>${escapeHtml(company.name)}</h2>
          <div class="pr-contact">${contact}</div>
          ${company.license ? `<p class="pr-license">Licence ${escapeHtml(company.license)}</p>` : ''}
        </div>
        <div class="pr-meta">
          <p class="pr-kicker">Proposal</p>
          <p><strong>${escapeHtml(proposal.reference)}</strong></p>
          <p>${escapeHtml(formatDate(proposal.issuedOn))}</p>
        </div>
      </header>

      <div class="pr-parties">
        <div class="pr-block"><h3>Prepared for</h3>
          <p><strong>${escapeHtml(client.name)}</strong></p>
          ${paragraphs(client.address)}
        </div>
        <div class="pr-block"><h3>Work</h3>
          <p><strong>${escapeHtml(job.title)}</strong></p>
        </div>
      </div>

      ${block('Scope of work', list(job.scope))}
      ${block('Not included', list(job.exclusions))}
      ${block('Notes', paragraphs(job.notes))}

      <table class="pr-price">
        <tbody>
          <tr class="pr-total"><td>Total price</td><td>${amount(pricing.price)}</td></tr>
          ${depositRow}
        </tbody>
      </table>
      ${validity}
      ${block('Payment terms', paragraphs(pricing.paymentTerms))}

      <div class="pr-sign">
        <div><span class="pr-rule"></span><p>Customer signature</p></div>
        <div><span class="pr-rule"></span><p>Date</p></div>
      </div>

      ${disclaimer ? `<p class="pr-disclaimer">${escapeHtml(disclaimer)}</p>` : ''}
    </article>
  `;
}

/**
 * Read the saved business block. A corrupt or absent entry is an empty block,
 * never an exception: a broken localStorage value must not stop someone
 * pricing a job.
 */
export function loadCompany(storage, key) {
  try {
    const saved = JSON.parse(storage?.getItem(key) || '{}');
    return Object.fromEntries(
      COMPANY_FIELDS.map((field) => [field, text(saved?.[field])]),
    );
  } catch {
    return Object.fromEntries(COMPANY_FIELDS.map((field) => [field, '']));
  }
}

/**
 * Persist the business block only. `CLIENT_FIELDS` are excluded by
 * construction, not by the caller remembering to strip them.
 */
export function saveCompany(storage, key, values = {}) {
  const payload = Object.fromEntries(
    COMPANY_FIELDS.map((field) => [field, text(values[field])]),
  );
  try {
    storage?.setItem(key, JSON.stringify(payload));
  } catch {
    // A full or disabled localStorage is not worth an error in front of the
    // customer; the proposal still prints, it just will not be pre-filled next
    // time.
  }
  return payload;
}

export function forgetCompany(storage, key) {
  try {
    storage?.removeItem(key);
  } catch {
    // Same reasoning as saveCompany.
  }
}

share.mjs.text:
// A technician quoting a job with a partner, or re-opening this tool on a
// different device, has to retype thirteen numbers every time -- techs,
// hours, PPE cost, waste pounds, and the rest -- because the only state this
// page kept was whatever was still in the tab. This module lets the whole
// bid scenario travel: to the visitor's own browser between visits, and into
// a link they can send themselves or a partner.
//
// Nothing here is transmitted. `localStorage` is the visitor's own disk, and
// the link is only ever built in their browser and copied by them. The
// scenario travels in the URL *fragment* (`#...`), never the query string: a
// fragment is not sent in the request line a server logs, nor in a
// `Referer` header a later click would carry.
//
// The required field list is imported from `calc.mjs`'s `DEFAULTS` rather
// than restated here, so a field added to the arithmetic is shareable the
// moment it exists -- this portfolio has twice paid for a copied field list
// going stale instead of being derived (see CLAUDE.md, "168 became 169").
//
// `proposedPrice` is the one field that is not: it is only present once a
// technician has a real quote to check, and `''` (nothing typed yet) is a
// materially different state from `0` (a giveaway job). Leaving it out of
// the link would ship the exact silent-divergence defect this portfolio has
// shipped before (a link that dropped fields, so the recipient computed a
// different profit than the sender saw) -- here a partner who opens a
// shared link would no longer see the price the sender was checking, and
// the "check a quoted price" panel would go quiet with nothing on screen to
// say why. `formValues` still clears any field a link does not carry,
// rather than leaving it unwritten: the same link could be opened on a page
// mid-edit or holding a saved draft, and leaving a stale value sitting in an
// unrelated field would silently mix the sender's price with a stranger's
// labor rate.

import { DEFAULTS } from './calc.mjs';

/** Every field `calculateJobBid` requires -- calc.mjs's own DEFAULTS keys. */
export const REQUIRED_FIELD_IDS = Object.freeze(Object.keys(DEFAULTS));

/** The one field the arithmetic treats as optional. See the header comment
 * above for why a link with nothing checked must leave this cleared, not
 * defaulted to 0 or left holding the recipient's own leftover figure. */
export const OPTIONAL_FIELD_IDS = Object.freeze(['proposedPrice']);

export const FIELD_IDS = Object.freeze([...REQUIRED_FIELD_IDS, ...OPTIONAL_FIELD_IDS]);

// The proposal panel's terms (`platform/proposal/adopt.mjs`), which also ride
// the link and the saved draft -- otherwise a shared link opens the sender's
// price under the recipient's own default deposit and terms, the defect
// `platform/proposal/term-ids.test.mjs` guards against. Named here, rather
// than left to `adopt.mjs`'s own copy, for the same reason `REQUIRED_FIELD_IDS`
// above is derived instead of restated: `term-ids.test.mjs` asserts the two
// agree.
export const TERM_NUMBER_FIELD_IDS = Object.freeze(['depositPercent', 'validDays']);
export const TERM_TEXT_FIELD_IDS = Object.freeze(['paymentTerms', 'proposalNotes', 'proposalExclusions']);

// Matches `MAX_TERM_TEXT` in the vendored `withProposalTerms` module
// (`platform/proposal/README.md`) so the two share mechanisms on this site
// agree about what fits in a fragment.
export const MAX_TERM_TEXT = 512;

function usableNumber(value) {
  if (value === '' || value === null || value === undefined) return null;
  if (String(value).trim() === '') return null;
  const result = Number(value);
  return Number.isFinite(result) && result >= 0 ? result : null;
}

// Prose is carried as typed, newlines included -- these are textareas, and a
// multi-line exclusions list is multiple lines on the customer's sheet. Only
// the control characters no textarea produces are stripped, plus surrounding
// whitespace, so a field holding only a stray newline reads as empty rather
// than as terms the sender wrote. Over-long text is dropped, not truncated:
// half a payment-terms clause presented to the recipient as the sender's
// terms is worse than the field arriving empty.
function usableText(value) {
  if (typeof value !== 'string') return null;
  // eslint-disable-next-line no-control-regex
  const clean = value.replace(/[\u0000-\u0008\u000B\u000C\u000E-\u001F\u007F]/g, '').trim();
  if (!clean) return null;
  return clean.length > MAX_TERM_TEXT ? null : clean;
}

export function encodeInputs(input) {
  const params = new URLSearchParams();
  for (const id of [...FIELD_IDS, ...TERM_NUMBER_FIELD_IDS]) {
    const value = usableNumber(input?.[id]);
    if (value !== null) params.set(id, String(value));
  }
  for (const id of TERM_TEXT_FIELD_IDS) {
    const value = usableText(input?.[id]);
    if (value !== null) params.set(id, value);
  }
  return params.toString();
}

export function decodeInputs(source) {
  const params = new URLSearchParams(String(source || '').replace(/^[?#]/, ''));
  const result = {};
  for (const id of [...FIELD_IDS, ...TERM_NUMBER_FIELD_IDS]) {
    if (!params.has(id)) continue;
    const value = usableNumber(params.get(id));
    if (value !== null) result[id] = value;
  }
  for (const id of TERM_TEXT_FIELD_IDS) {
    if (!params.has(id)) continue;
    const value = usableText(params.get(id));
    if (value !== null) result[id] = value;
  }
  return result;
}

/**
 * Every field the form owns, as the string a form control holds -- the
 * shared value where the link had one, and `''` where it did not.
 */
export function formValues(decoded) {
  const source = decoded || {};
  const ids = [...FIELD_IDS, ...TERM_NUMBER_FIELD_IDS, ...TERM_TEXT_FIELD_IDS];
  return Object.fromEntries(ids.map((id) => [id, id in source ? String(source[id]) : '']));
}

/**
 * Which term text fields are too long to ride in a link -- named to the
 * sender at the moment they copy, the same reasoning as
 * `platform/proposal/README.md`'s `overlongTerms`.
 */
export function overlongTerms(values) {
  return TERM_TEXT_FIELD_IDS.filter((id) => {
    const raw = values?.[id];
    return typeof raw === 'string' && raw.trim().length > MAX_TERM_TEXT;
  });
}

usage.mjs.text:
const KEY = 'biohazard-cleanup-bid-calculator-usage';
const OPT_OUT = 'biohazard-cleanup-bid-calculator-usage-opt-out';

function storage() {
  try {
    return typeof localStorage !== 'undefined' ? localStorage : null;
  } catch {
    return null;
  }
}

export function usageAllowed() {
  if (typeof navigator !== 'undefined' && (navigator.doNotTrack === '1' || navigator.globalPrivacyControl)) {
    return false;
  }
  const ls = storage();
  if (!ls) return false;
  return ls.getItem(OPT_OUT) !== 'true';
}

export function recordEvent(event = 'bid-calculated') {
  if (!usageAllowed()) return;
  try {
    const ls = storage();
    if (!ls) return;
    const counts = JSON.parse(ls.getItem(KEY) || '{}');
    counts[event] = (counts[event] || 0) + 1;
    ls.setItem(KEY, JSON.stringify(counts));
  } catch { /* Private browsing must not break the calculator. */ }
}

export function toggleUsage(enabled) {
  try {
    const ls = storage();
    if (!ls) return;
    ls.setItem(OPT_OUT, enabled ? 'false' : 'true');
  } catch { /* optional measurement */ }
}
